package com.aaliyun.leadnews.wemedia.config;import io.minio.MinioClient;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.*;@Configuration @EnableConfigurationProperties(WemediaMinioProperties.class)public class WemediaStorageConfiguration{@Bean MinioClient wemediaMinioClient(WemediaMinioProperties p){return MinioClient.builder().endpoint(p.endpoint()).credentials(p.accessKey(),p.secretKey()).build();}}
